mapper.select:
SELECT

FROM memories

    workspace_uuid = #{params.WorkspaceUUID}
    AND memory_store_external_id = #{params.MemoryStoreExternalID}
    AND deleted_at IS NULL

        AND LEFT(path, LENGTH(#{params.PathPrefix})) = #{params.PathPrefix}


        AND (




                        created_at < #{params.CursorCreatedAt}
                        OR (created_at = #{params.CursorCreatedAt} AND uuid < #{params.CursorUUID})


                        created_at > #{params.CursorCreatedAt}
                        OR (created_at = #{params.CursorCreatedAt} AND uuid > #{params.CursorUUID})






                        updated_at < #{params.CursorUpdatedAt}
                        OR (updated_at = #{params.CursorUpdatedAt} AND uuid < #{params.CursorUUID})


                        updated_at > #{params.CursorUpdatedAt}
                        OR (updated_at = #{params.CursorUpdatedAt} AND uuid > #{params.CursorUUID})






                        path < #{params.CursorPath}
                        OR (path = #{params.CursorPath} AND uuid < #{params.CursorUUID})


                        path > #{params.CursorPath}
                        OR (path = #{params.CursorPath} AND uuid > #{params.CursorUUID})




        )


ORDER BY

    created_at
    updated_at
    path


    DESC, uuid DESC
    ASC, uuid ASC

LIMIT #{params.Limit}

SELECT

FROM memories
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND memory_store_external_id = #{params.MemoryStoreExternalID}
AND deleted_at IS NULL

    AND LEFT(path, LENGTH(#{params.PathPrefix})) = #{params.PathPrefix}

ORDER BY path ASC, uuid ASC

SELECT external_id
FROM memories
WHERE workspace_uuid = #{workspaceUUID}
AND memory_store_uuid = #{storeUUID}
AND path = #{path}

    AND uuid <> #{excludeMemoryUUID}

AND deleted_at IS NULL
LIMIT 1

SELECT CAST(COUNT(*) AS integer)
FROM memories
WHERE workspace_uuid = #{workspaceUUID}
AND memory_store_external_id = #{memoryStoreExternalID}
AND current_version_uuid = #{versionUUID}
AND deleted_at IS NULL

